const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const axis=(xl,yl)=>`<path d="M60 25v330h630" stroke="#8ba89a" fill="none"/><text x="350" y="395" fill="#71877a" font-size="11">${xl}</text><text x="15" y="190" fill="#71877a" font-size="10" transform="rotate(-90 15 190)">${yl}</text>`;
const svg=(inside)=>`<svg class="specialist-svg" viewBox="0 0 760 420" role="img" aria-label="Synthetic specialist visualization">${inside}</svg>`;
function crossplot(kind){let points=Array.from({length:95},(_,i)=>{let x=90+(i*137%580),y=320-((i*43%200)*.7+(x-90)*.15);return`<circle data-sample="${i+1}" role="button" tabindex="0" aria-label="Inspect sample ${i+1}" cx="${x}" cy="${y}" r="3.5" fill="${i%4===0?'#bca26a':'#328e78'}" opacity=".7"/>`;}).join('');return svg(axis(kind==='saturation'?'Porosity / fraction (log display example)':'Density / g·cm⁻³',kind==='saturation'?'Resistivity / Ω·m':'Neutron / fraction')+`<path d="M90 320 680 80M90 280 580 40" stroke="#96b8a3" stroke-dasharray="5 5" fill="none"/>${points}<text x="90" y="45" fill="#71877a" font-size="10">Synthetic points · select to inspect</text>`);}
function spectra(){let out='';for(let j=0;j<13;j++){let pts=Array.from({length:80},(_,i)=>`${80+i*7.8},${48+j*22-Math.exp(-(((i-25-j*1.8)/10)**2))*30}`).join(' ');out+=`<polyline fill="none" stroke="${j%3===0?'#b29a5f':'#188674'}" stroke-width="1.4" points="${pts}"/>`;}return svg(`<rect x="75" y="25" width="625" height="340" fill="#f7faf6"/><path d="M350 25v340" stroke="#b27d36" stroke-dasharray="6 4"/>${out}<text x="355" y="42" fill="#a57a3b" font-size="11">T2 cutoff</text><text x="310" y="400" fill="#71877a" font-size="11">Relaxation time / log scale · synthetic spectra</text>`);}
function imageLog(){let out='';for(let y=0;y<45;y++)for(let x=0;x<38;x++){let n=(Math.sin(x*.5+y*.2)+Math.cos(y*.8+x*.1)+2)/4;out+=`<rect x="${120+x*12}" y="${30+y*7.2}" width="12" height="7.4" fill="hsl(${35+n*10},${30+n*40}%,${25+n*55}%)"/>`;}return svg(out+`<path d="M120 180q110-140 220 0t235 0" stroke="#e9f6df" stroke-width="2" fill="none"/><text x="120" y="385" font-size="11" fill="#71877a">0°</text><text x="540" y="385" font-size="11" fill="#71877a">360° azimuth</text><text x="120" y="20" font-size="10" fill="#71877a">Synthetic electrical image · no tool data connected</text>`);}
function seismic(){let out='';for(let x=0;x<90;x++){let pts=[];for(let y=0;y<120;y++){let wave=Math.sin(y*.48+x*.075)*Math.cos(y*.11)*2.8;pts.push(`${65+x*7+wave},${30+y*2.7}`);}out+=`<polyline points="${pts.join(' ')}" stroke="#53786b" stroke-width=".7" opacity=".7" fill="none"/>`;}return svg(`<rect x="60" y="25" width="645" height="335" fill="#f2f6ee"/>${out}<path d="M70 170q220-30 310 20t320-40" fill="none" stroke="#bc8c3f" stroke-width="2"/><text x="70" y="390" font-size="11" fill="#71877a">Trace index · synthetic section</text><text x="15" y="180" font-size="10" fill="#71877a" transform="rotate(-90 15 180)">Two-way travel time</text>`);}
function model(view){let out='';for(let i=0;i<14;i++){let a=120+i*34;out+=`<path d="M${a} 130q100-70 190-15l110 115q-120-30-190 15z" fill="${view==='Properties'?'#78b39e20':'none'}" stroke="#72a38a" stroke-width=".8"/>`;}for(let i=0;i<8;i++)out+=`<path d="M${120+i*16} ${130+i*17}q180-120 430-20" fill="none" stroke="#a8c2a9"/>`;return svg(`<g transform="translate(-30 0)">${out}<path d="M430 80v250l40-15V65" fill="#bd9b6944" stroke="#b69d76"/><path d="m290 100 30 180" stroke="#087f74" stroke-width="3"/></g><text x="100" y="395" fill="#71877a" font-size="11">Illustrative ${e(view.toLowerCase())} · not a calculated earth model</text>`);}
function timeSeries(){let pts=Array.from({length:80},(_,i)=>`${80+i*7.5},${70+Math.log(1+i)*55+Math.sin(i*.7)*8}`).join(' ');return svg(axis('Time / example sequence','Normalized response')+`<polyline fill="none" stroke="#178b76" stroke-width="2" points="${pts}"/><path d="M400 25v330" stroke="#bc9453" stroke-dasharray="5 5"/><text x="405" y="45" fill="#a17b41" font-size="10">Review boundary</text>`);}
function histogram(){return svg(axis('Parameter / normalized bins','Frequency')+Array.from({length:24},(_,i)=>{let h=260*Math.exp(-(((i-12)/5)**2));return `<rect x="${90+i*24}" y="${350-h}" width="18" height="${h}" rx="2" fill="${i===12?'#b99b60':'#76ad94'}"/>`;}).join('')+`<path d="M390 40v310" stroke="#b28742" stroke-dasharray="5 4"/>`);}
function digitize(){return svg(`<rect x="120" y="15" width="465" height="370" fill="#faf9ee" stroke="#d7dccb"/><defs><pattern id="scan-grid" width="25" height="15" patternUnits="userSpaceOnUse"><path d="M25 0H0V15" stroke="#d5d7c9" stroke-width=".6" fill="none"/></pattern></defs><rect x="145" y="35" width="410" height="325" fill="url(#scan-grid)"/><path d="${Array.from({length:95},(_,i)=>`${i?'L':'M'}${280+Math.sin(i*.23)*55+Math.cos(i*.7)*15} ${40+i*3.3}`).join(' ')}" fill="none" stroke="#435f50" stroke-width="1.3"/><path d="M145 70h410M145 320h410" stroke="#139a88" stroke-dasharray="5 3"/><circle cx="145" cy="70" r="5" fill="#139a88"/><circle cx="145" cy="320" r="5" fill="#139a88"/><text x="600" y="75" font-size="11" fill="#458577">Top depth anchor</text><text x="600" y="325" font-size="11" fill="#458577">Bottom anchor</text><text x="120" y="410" font-size="10" fill="#71877a">Synthetic raster page for layout review · source upload required</text>`);}
function rows(headers,rows){return`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export function specialist(m,state){let ui=state.workbenchUI?.[m.id]||{}, view=ui.view||'Primary';let types=['seismic','rockphysics'].includes(m.id)?['Section','Well tie','Attributes']:['structure','properties','planning','simulation','trajectories'].includes(m.id)?['Structure','Properties','Cross section']:['digitize','images'].includes(m.id)?['Image','Calibration','Picks']:['production','pressure','geomechanics'].includes(m.id)?['Profile','Crossplot','Table']:['nmr','height','core'].includes(m.id)?['Distribution','Crossplot','Table']:['opportunities'].includes(m.id)?['Candidates','Evidence','Decisions']:['uncertainty','volumes'].includes(m.id)?['Distribution','Sensitivity','Cases']:['Curves','Crossplot','Table'];if(!types.includes(view))view=types[0];let graphic;if(m.id==='digitize')graphic=digitize();else if(m.id==='images')graphic=imageLog();else if(m.id==='seismic'||m.id==='rockphysics')graphic=seismic();else if(['structure','properties','planning','simulation','trajectories'].includes(m.id))graphic=model(view);else if(m.id==='nmr')graphic=spectra();else if(['volumes','uncertainty'].includes(m.id))graphic=histogram();else if(['production','pressure','geomechanics'].includes(m.id))graphic=timeSeries();else graphic=crossplot(m.id);if(view==='Crossplot')graphic=crossplot(m.id);if(view==='Table')graphic=rows(['Sample','Depth / ft','Example input','Quality'],Array.from({length:10},(_,i)=>[i+1,4200+i*5,(.12+i*.01).toFixed(2),'Synthetic']));let candidate=m.id==='opportunities';if(candidate)graphic=rows(['Candidate','Well / zone','Evidence','Review'],[['EX-001','TMB-02 / Zone A','Synthetic example only',state.candidateDecision||'Not reviewed'],['EX-002','TMB-04 / Zone B','Missing completion evidence','Insufficient evidence']])+`<div class="panel-body"><button data-action="candidate-review">Review selected candidate</button></div>`;
return `<div class="panel"><div class="toolbar"><select id="workbench-well" aria-label="Workbench well">${['TMB-01','TMB-02','TMB-04','TMB-05','TMB-06','TMB-07'].map(w=>`<option ${state.well===w?'selected':''}>${w}</option>`).join('')}</select><div class="pill-group">${types.map(t=>`<button data-view="${e(t)}" class="${t===view?'active':''}">${e(t)}</button>`).join('')}</div><span class="badge gray">Synthetic visual reference</span><button data-action="workbench-annotation">Add annotation</button></div><div class="specialist-layout"><aside class="tool-rail"><div class="label">${e(m.name)} tools</div>${m.features.map((t,i)=>`<button class="tool-button ${ui.feature===t?'selected':''}" data-feature="${e(t)}"><span>${String(i+1).padStart(2,'0')}</span>${e(t)}</button>`).join('')}<div class="note" style="margin-top:18px">Tools save review specifications. Connected data and computations are pending.</div></aside><div class="visual-canvas">${graphic}<div class="toolbar"><label class="layer"><input id="show-overlay" type="checkbox" ${ui.overlay!==false?'checked':''}>Show interpretation overlay</label><label class="layer"><input id="link-depth" type="checkbox" ${ui.linkDepth!==false?'checked':''}>Link depth selection</label><button data-action="workbench-reset-view">Reset view</button></div><div class="panel-body"><div class="label">Annotations</div>${(state.annotations?.[m.id]||[]).map(a=>`<div class="status-row"><span>${e(a.text)}</span><small>${e(a.reference)}</small></div>`).join('')||'<p class="sub" style="margin-top:10px">No review annotations yet.</p>'}</div></div></div></div><div class="note" style="margin-bottom:20px">Visual reference for frontend review. This is not a processed ${e(m.name.toLowerCase())} result. The Parameters and Inputs tabs retain the integration configuration.</div>`;}
